const $ = s => document.querySelector(s);
let activeFoodsafeUser=null;
const state = {banks:[],questions:[],session:[],index:0,answers:{},mode:'practice',attempts:{},bookmarks:[],revisionMode:false};
function load(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function userStoreKey(k){return 'foodsafe_user_'+activeFoodsafeUser+'_'+k;}
function save(){if(!activeFoodsafeUser)return;localStorage.setItem(userStoreKey('attempts'),JSON.stringify(state.attempts));localStorage.setItem(userStoreKey('bookmarks'),JSON.stringify(state.bookmarks));}
function loadUserProgress(username){activeFoodsafeUser=username;state.attempts=load(userStoreKey('attempts'),{});state.bookmarks=load(userStoreKey('bookmarks'),[]);refresh();}
const DAY=86400000;
function scheduleAnswer(q,letter,source='practice'){const prev=state.attempts[q.id]||{};const correct=letter===q.correct_option;const now=Date.now();let reps=prev.repetitions||0;let interval=prev.intervalDays||0;if(correct){reps++;interval=reps===1?1:reps===2?3:reps===3?7:Math.min(60,Math.round(interval*2.2));}else{reps=0;interval=0.007;}state.attempts[q.id]={...prev,correct,selected:letter||'',bank:q._bank,topic:q.topic,subject:q._subject,date:now,lastReviewed:now,nextReview:now+interval*DAY,intervalDays:interval,repetitions:reps,lapses:(prev.lapses||0)+(correct?0:1),source};}
function dueQuestions(){const now=Date.now();return state.questions.filter(q=>{const a=state.attempts[q.id];return a&&a.nextReview&&a.nextReview<=now;}).sort((a,b)=>(state.attempts[a.id].nextReview||0)-(state.attempts[b.id].nextReview||0));}
function renderRevision(){const due=dueQuestions(),vals=state.questions.map(q=>state.attempts[q.id]).filter(Boolean),mastered=vals.filter(a=>(a.repetitions||0)>=4).length,learning=vals.length-mastered,newCount=state.questions.length-vals.length;$('#rev-due').textContent=due.length;$('#rev-learning').textContent=learning;$('#rev-mastered').textContent=mastered;$('#rev-new').textContent=newCount;$('#nav-due-count').textContent=due.length;$('#revision-queue').innerHTML=due.length?due.slice(0,12).map(q=>{const a=state.attempts[q.id];return `<div class="revision-row"><span class="rev-mark">↻</span><span class="rev-copy"><b>${esc(q.question)}</b><small>${esc(q._subject)} · ${esc(q.topic)} · ${a.lapses||0} previous misses</small></span><span class="rev-status">DUE</span></div>`}).join(''):'<div class="empty-state">Nothing is due right now. Keep practising; missed questions and new learning will appear here automatically.</div>';$('#start-revision').disabled=!due.length;$('#start-revision').style.opacity=due.length?1:.55;}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function norm(raw,source='Imported file'){
 if(!raw||!Array.isArray(raw.questions))throw Error('This JSON must contain a "questions" array.');
 const meta=raw.metadata||{};const title=raw.title||meta.title||raw.bank_title||source;const subject=raw.subject||meta.subject||'Uncategorised';const chapter=raw.chapter||meta.chapter||'';
 // Support banks that store answers and explanations separately from questions.
 const answerRows=Array.isArray(raw.answer_key)?raw.answer_key:(Array.isArray(raw.answers)?raw.answers:[]);const answerMap=new Map();
 answerRows.forEach((a,i)=>{if(a&&typeof a==='object'){const id=a.question_id||a.id;if(id)answerMap.set(String(id),a.correct_option??a.correct_answer??a.answer??a.correctAnswer??'');else answerMap.set(String(i),a.correct_option??a.correct_answer??a.answer??a.correctAnswer??'');}});
 if(raw.answer_key&&!Array.isArray(raw.answer_key)&&typeof raw.answer_key==='object')Object.entries(raw.answer_key).forEach(([k,v])=>answerMap.set(String(k),typeof v==='object'?(v.correct_option??v.correct_answer??v.answer??''):v));
 const explanationRows=Array.isArray(raw.detailed_explanations)?raw.detailed_explanations:(Array.isArray(raw.explanations)?raw.explanations:[]);const explanationMap=new Map();
 explanationRows.forEach((e,i)=>{if(e&&typeof e==='object'){const id=e.question_id||e.id;if(id)explanationMap.set(String(id),e);else explanationMap.set(String(i),e);}});
 const qs=raw.questions.map((q,i)=>{const opts=q.options||q.choices||{};let options=Array.isArray(opts)?opts.map((v,j)=>[String.fromCharCode(65+j),typeof v==='string'?v:(v.text||v.value||'')]):Object.entries(opts).map(([k,v])=>[k,typeof v==='string'?v:(v.text||v.value||'')]);const id=String(q.id||`${source}-${i+1}`);const separateAnswer=answerMap.has(id)?answerMap.get(id):answerMap.get(String(i));let correct=q.correct_option??q.correct_answer??q.answer??q.correctAnswer??separateAnswer??'';if(typeof correct==='number')correct=String.fromCharCode(65+correct);correct=String(correct).trim().toUpperCase();const separateExplanation=explanationMap.get(id)||explanationMap.get(String(i))||{};const explanation=q.explanation||q.solution||q.detailed_explanation||separateExplanation.detailed_explanation||separateExplanation.explanation||'';if(!q.question||options.length<2||!options.every(([,v])=>String(v).trim())||!options.some(([k])=>k.toUpperCase()===correct))throw Error(`Question ${i+1} (${q.id||'no ID'}) has missing text, options or an invalid correct answer.`);return {...q,id,question:q.question,options,correct_option:correct,explanation,why_other_options_are_incorrect:q.why_other_options_are_incorrect||separateExplanation.why_other_options_are_incorrect||{},topic:q.topic||chapter||q.module||'General',difficulty:q.difficulty||'Unspecified',section_reference:q.section_reference||q.reference||'',_bank:title,_subject:q.subject||subject,_chapter:q.chapter||q.module||chapter};});
 return {title,subject,chapter,questions:qs,source};
}
function addBank(raw,source){const bank=norm(raw,source);const existing=new Set(state.questions.map(q=>q.id));const dup=bank.questions.filter(q=>existing.has(q.id));if(dup.length)throw Error(`Duplicate question ID found: ${dup[0].id}. Give each question a unique ID.`);state.banks.push(bank);state.questions.push(...bank.questions);return bank;}
async function init(){try{const r=await fetch('content/manifest.json');if(r.ok){const m=await r.json();for(const entry of (m.questionBanks||[])){try{const res=await fetch(entry.file);if(!res.ok)throw Error('File not found');const b=addBank(await res.json(),entry.file);if(entry.subject)b.subject=entry.subject;if(entry.chapter)b.chapter=entry.chapter;}catch(e){console.warn('Could not load',entry.file,e.message)}}}}catch(e){console.info('Manifest not loaded; local import remains available.');}refresh();}
function refresh(){const sections=[...new Set(state.questions.map(q=>q._bank))];$('#stat-total').textContent=state.questions.length;$('#nav-q-count').textContent=state.questions.length;$('#stat-banks').textContent=`${state.banks.length} sections loaded`;$('#stat-attempted').textContent=Object.keys(state.attempts).length;$('#stat-bookmarks').textContent=state.bookmarks.length;const vals=Object.values(state.attempts);$('#stat-accuracy').textContent=vals.length?Math.round(vals.filter(x=>x.correct).length/vals.length*100)+'%':'—';$('#section-list').innerHTML=state.banks.length?state.banks.map((b,i)=>`<div class="section-row"><span class="section-emoji">${['✳','◈','▤','✦','◎'][i%5]}</span><span class="section-meta"><b>${esc(b.title)}</b><small>${esc(b.subject)}${b.chapter?' · '+esc(b.chapter):''}</small></span><span class="section-number">${b.questions.length}</span></div>`).join(''):'<div class="empty-state">No question-bank files loaded yet. Use “Import questions” to add your first JSON section.</div>';
 const select=$('#filter-section');const old=select.value;select.innerHTML='<option value="all">All sections</option>'+state.banks.map(b=>`<option value="${esc(b.title)}">${esc(b.title)}</option>`).join('');if(sections.includes(old))select.value=old;updateAvailable();renderAnalytics();renderRevision();}
function filtered(){const term=$('#search-q').value.toLowerCase(),section=$('#filter-section').value,diff=$('#filter-difficulty').value;return state.questions.filter(q=>(section==='all'||q._bank===section)&&(diff==='all'||q.difficulty.toLowerCase()===diff.toLowerCase())&&(!term||[q.question,q.topic,q.section_reference,q._bank].join(' ').toLowerCase().includes(term)));}
function updateAvailable(){$('#available-count').textContent=filtered().length+' questions';}
function startQuiz(){state.revisionMode=false;let pool=filtered();if(!pool.length)return toast('No questions match these filters. Import a JSON file or change filters.');if($('#question-order').value==='random')pool=[...pool].sort(()=>Math.random()-.5);const limit=$('#question-limit').value;state.session=limit==='all'?pool:pool.slice(0,Number(limit));state.index=0;state.answers={};state.mode=$('#filter-mode').value;$('#quiz-idle').classList.add('hide');$('#quiz-results').classList.add('hide');$('#quiz-active').classList.remove('hide');renderQuestion();}
function renderQuestion(){const q=state.session[state.index],selected=state.answers[q.id];const revealed=state.mode==='practice'&&selected;const letters=q.options.map(x=>x[0]);$('#quiz-active').innerHTML=`<div class="question-card-top"><span class="q-kicker">QUESTION ${state.index+1} <span style="color:#c5c3d1">/ ${state.session.length}</span></span><div class="q-tags"><span class="q-tag">${esc(q.difficulty)}</span><span class="q-tag">${esc(q.topic)}</span></div></div><div class="question-text">${esc(q.question)}</div><div class="option-list">${q.options.map(([k,v])=>{let cls='';if(selected&&k.toUpperCase()===q.correct_option)cls='correct';else if(revealed&&selected===k&&selected!==q.correct_option)cls='incorrect';else if(selected===k)cls='selected';return `<button class="option ${cls}" data-option="${esc(k)}" ${selected?'disabled':''}><span class="letter">${esc(k)}</span><span>${esc(v)}</span></button>`}).join('')}</div>${revealed?`<div class="explanation"><b>${selected===q.correct_option?'✓ CORRECT ANSWER':'✕ NOT QUITE — CORRECT ANSWER: '+esc(q.correct_option)}</b>${esc(q.explanation||'No explanation was supplied in this question-bank file.')}</div>`:''}<div class="quiz-controls"><button class="text-btn" id="bookmark-question">${state.bookmarks.includes(q.id)?'⚑ Bookmarked':'⚐ Bookmark question'}</button>${state.mode==='practice'?`<button class="btn btn-primary" id="next-question" ${selected?'':'disabled'}>${state.index===state.session.length-1?'Finish session':'Next question'} →</button>`:`<span class="q-kicker">${Object.keys(state.answers).length} ANSWERED</span><button class="btn btn-primary" id="next-question" ${selected?'':'disabled'}>${state.index===state.session.length-1?'Submit test':'Next question'} →</button>`}</div>`;
 $('#quiz-active').querySelectorAll('[data-option]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.option)));$('#next-question').addEventListener('click',()=>{if(state.index<state.session.length-1){state.index++;renderQuestion()}else finishQuiz()});$('#bookmark-question').addEventListener('click',toggleBookmark);}
function choose(letter){const q=state.session[state.index];if(state.answers[q.id])return;state.answers[q.id]=letter;if(state.mode==='practice'){scheduleAnswer(q,letter,state.revisionMode?'revision':'practice');save()}renderQuestion();}
function toggleBookmark(){const id=state.session[state.index].id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();refresh();renderQuestion();}
function finishQuiz(){let correct=0,wrong=0,unanswered=0;state.session.forEach(q=>{const a=state.answers[q.id];if(!a)unanswered++;else if(a===q.correct_option)correct++;else wrong++;scheduleAnswer(q,a||'',state.revisionMode?'revision':'test')});save();const score=correct-wrong*.25;$('#quiz-active').classList.add('hide');$('#quiz-results').classList.remove('hide');$('#quiz-results').innerHTML=`<div style="text-align:center;padding:20px"><div class="eyebrow muted">SESSION COMPLETE</div><h2 style="font:800 25px var(--head)">Good work. Keep building.</h2><div class="result-score">${score.toFixed(2)}<small style="font:500 11px var(--font);color:#999"> net score*</small></div><p style="color:#9291a5;font-size:10px">${correct} correct · ${wrong} incorrect · ${unanswered} unanswered</p><div class="result-list"><div class="result-row"><span>Accuracy</span><b>${correct+wrong?Math.round(correct/(correct+wrong)*100):0}%</b></div><div class="result-row"><span>Questions in session</span><b>${state.session.length}</b></div><div class="result-row"><span>Marking used</span><b>+1 / −0.25*</b></div></div><p style="font-size:9px;color:#aaa;margin:13px 0">*Practice scoring preset only. Confirm the applicable HPSC notification before using an official exam simulation.</p><button class="btn btn-primary" id="again">Start another session →</button></div>`;$('#again').addEventListener('click',()=>{$('#quiz-results').classList.add('hide');$('#quiz-idle').classList.remove('hide');refresh()});refresh();state.revisionMode=false;}
function startRevision(){const pool=dueQuestions();if(!pool.length)return toast('No questions are due right now.');state.session=pool;state.index=0;state.answers={};state.mode='practice';state.revisionMode=true;go('practice');$('#quiz-idle').classList.add('hide');$('#quiz-results').classList.add('hide');$('#quiz-active').classList.remove('hide');renderQuestion();}
function renderAnalytics(){const vals=Object.values(state.attempts),correct=vals.filter(v=>v.correct).length,wrong=vals.length-correct,acc=vals.length?Math.round(correct/vals.length*100):0;$('#analytics-accuracy').innerHTML=`${vals.length?acc+'%':'—'}<small>accuracy</small>`;$('#accuracy-bar').style.width=acc+'%';$('#analytics-correct').textContent=correct;$('#analytics-wrong').textContent=wrong;$('#analytics-attempted').textContent=vals.length;const by={};vals.forEach(v=>{const k=v.bank||'Other';by[k]??={n:0,c:0};by[k].n++;if(v.correct)by[k].c++});const rows=Object.entries(by);$('#section-performance').innerHTML=rows.length?rows.map(([k,v])=>`<div class="performance-row"><b>${esc(k)}</b><div class="performance-track"><span style="width:${Math.round(v.c/v.n*100)}%"></span></div><span>${Math.round(v.c/v.n*100)}%</span></div>`).join(''):'Answer some questions to see your section-wise performance.';}
function importFiles(files){[...files].forEach(file=>{const reader=new FileReader();reader.onload=()=>{try{const bank=addBank(JSON.parse(reader.result),file.name);refresh();toast(`Added ${bank.questions.length} questions from ${file.name}`)}catch(e){toast(`Could not import ${file.name}: ${e.message}`)}};reader.onerror=()=>toast(`Could not read ${file.name}`);reader.readAsText(file)});}
function go(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent=view.toUpperCase();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#theme-toggle').addEventListener('click',()=>document.body.classList.toggle('dark'));['#search-q','#filter-section','#filter-difficulty'].forEach(s=>$(s).addEventListener(s==='#search-q'?'input':'change',updateAvailable));$('#start-quiz').addEventListener('click',startQuiz);['#practice-import','#quick-import','#banner-import'].forEach(s=>$(s).addEventListener('click',()=>$('#json-upload').click()));$('#json-upload').addEventListener('change',e=>{if(e.target.files.length)importFiles(e.target.files);e.target.value=''});$('#start-revision').addEventListener('click',startRevision);$('#clear-progress').addEventListener('click',()=>{if(confirm('Delete all locally saved attempts and bookmarks?')){state.attempts={};state.bookmarks=[];save();refresh();toast('Local progress cleared.')}});
/* PHASE 2 — Full Examination Simulator */
const examState = { pool:[], answers:{}, marked:[], index:0, seconds:0, duration:0, positive:1, negative:0.25, timer:null, startedAt:null, submitted:false, title:"" };
function examInject(){
  const nav=document.querySelector('.nav-list');
  if(nav && !document.querySelector('[data-view="exam"]')){
    const b=document.createElement('button'); b.className='nav-link'; b.dataset.view='exam'; b.innerHTML='<i>◷</i> Examination simulator'; b.addEventListener('click',()=>go('exam')); nav.insertBefore(b,nav.querySelector('[data-view="revision"]'));
  }
  const wrap=document.querySelector('.page-wrap');
  if(wrap && !document.getElementById('view-exam')){
    const s=document.createElement('section'); s.className='view'; s.id='view-exam';
    s.innerHTML=`
      <div class="page-title-row"><div><div class="eyebrow muted">REALISTIC TEST CONDITIONS</div><h1>Examination simulator<span class="title-dot">.</span></h1><p>Timed tests, question palette, review flags and a detailed result sheet.</p></div></div>
      <div id="exam-setup" class="exam-setup-grid">
        <section class="panel exam-config"><div class="eyebrow muted">CONFIGURE YOUR MOCK</div><h3>Build an examination</h3>
          <label>Question source<select id="exam-section"><option value="all">All question-bank sections</option></select></label>
          <div class="exam-config-row"><label>Number of questions<select id="exam-count"><option>25</option><option selected>50</option><option>100</option><option value="all">All available</option></select></label><label>Duration<select id="exam-duration"><option value="30">30 minutes</option><option value="60" selected>60 minutes</option><option value="90">90 minutes</option><option value="120">120 minutes</option></select></label></div>
          <div class="exam-config-row"><label>Marks per correct<input id="exam-positive" type="number" min="0" step="0.25" value="1"></label><label>Penalty per wrong<input id="exam-negative" type="number" min="0" step="0.05" value="0.25"></label></div>
          <label class="exam-check"><input id="exam-random" type="checkbox" checked> Randomise question order</label>
          <label class="exam-check"><input id="exam-confirm" type="checkbox" checked> Ask before submitting early</label>
          <button class="btn btn-primary full" id="exam-start">Start examination →</button>
          <p class="exam-disclaimer">Marking is configurable. The default +1 / −0.25 is a practice preset, not a claim about the current official HPSC notification.</p>
        </section>
        <aside class="panel exam-rules"><div class="eyebrow muted">EXAM CONTROLS</div><h3>Know your controls</h3><ul><li><b>Save & Next</b> records your selected answer.</li><li><b>Mark for review</b> flags a question for another look.</li><li><b>Clear response</b> removes your selected option.</li><li><b>Question palette</b> jumps directly to any question.</li><li>The test submits automatically when the timer reaches zero.</li></ul><div class="exam-bank-count"><b id="exam-available">0</b><span>questions currently loaded</span></div></aside>
      </div>
      <section id="exam-live" class="hide"></section><section id="exam-results" class="hide"></section>`;
    wrap.appendChild(s);
  }
  const style=document.createElement('style'); style.textContent=`
  .exam-setup-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.exam-config label{display:block;font-size:10px;font-weight:700;color:#77768d;margin:15px 0}.exam-config select,.exam-config input[type=number]{display:block;width:100%;height:39px;margin-top:7px;padding:0 10px;border:1px solid #eeeef4;border-radius:9px;background:#fff;color:#555;font:500 11px var(--font)}.exam-config-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.exam-check{display:flex!important;align-items:center;gap:9px}.exam-check input{accent-color:#7657e8}.exam-disclaimer{font-size:9px;line-height:1.6;color:#999;margin-top:13px}.exam-rules ul{padding-left:18px;color:#77768d;font-size:11px;line-height:2}.exam-bank-count{display:flex;align-items:baseline;gap:9px;border-top:1px solid #eeeef4;padding-top:17px;margin-top:20px}.exam-bank-count b{font:800 30px var(--head);color:#7657e8}.exam-bank-count span{font-size:10px;color:#999}.exam-live-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.exam-timer{font:800 22px var(--head);color:#7657e8;background:#f2efff;border-radius:10px;padding:9px 14px;font-variant-numeric:tabular-nums}.exam-timer.warning{color:#c84f4f;background:#fff0ef}.exam-live-grid{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:14px}.exam-question{min-height:360px}.exam-qtext{font:700 17px/1.6 var(--head);margin:23px 0}.exam-option{width:100%;display:flex;gap:12px;align-items:flex-start;text-align:left;padding:13px;border:1px solid #eaeaf1;background:#fff;border-radius:10px;margin:9px 0;font:11px/1.5 var(--font);color:#34334c}.exam-option.chosen{border-color:#8a70e8;background:#f5f2ff}.exam-option .letter{width:24px;height:24px;flex:none;display:grid;place-items:center;background:#f3f2f8;border-radius:7px;font-weight:800}.exam-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:22px}.exam-actions button{font-size:10px}.exam-palette{height:max-content;position:sticky;top:15px}.exam-palette-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin:14px 0}.palette-btn{height:34px;border:1px solid #e8e7ef;border-radius:8px;background:#fff;color:#777;font-size:10px;font-weight:800}.palette-btn.answered{background:#e5f7ee;border-color:#b7e8d1;color:#23845d}.palette-btn.flagged{background:#fff3d9;border-color:#f4d18a;color:#986b13}.palette-btn.current{outline:2px solid #7657e8;outline-offset:1px}.exam-legend{font-size:9px;color:#9291a5;line-height:2}.exam-legend span{display:inline-block;width:8px;height:8px;border-radius:3px;margin:0 5px 0 8px}.exam-result-head{text-align:center;padding:12px}.exam-review-row{border-top:1px solid #eeeef4;padding:13px 0;font-size:10px;line-height:1.6}.exam-review-row b{display:block;margin-bottom:5px}.exam-review-row .ok{color:#23845d}.exam-review-row .bad{color:#c84f4f}.exam-review-row .skip{color:#9b7a30}.exam-result-toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.exam-stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:17px 0}.exam-stat{background:#faf9ff;border:1px solid #eeeaf8;border-radius:10px;padding:12px}.exam-stat span{display:block;color:#999;font-size:9px}.exam-stat b{display:block;font:800 20px var(--head);margin-top:4px}@media(max-width:850px){.exam-setup-grid,.exam-live-grid{grid-template-columns:1fr}.exam-palette{position:static}.exam-stat-grid{grid-template-columns:repeat(2,1fr)}}`;
  document.head.appendChild(style);
  const sel=document.getElementById('exam-section'); if(sel){const old=sel.value;sel.innerHTML='<option value="all">All question-bank sections</option>'+state.banks.map(b=>`<option value="${esc(b.title)}">${esc(b.title)}</option>`).join('');sel.value=old;}
  const av=document.getElementById('exam-available');if(av)av.textContent=state.questions.length;
}
function examStart(){
  let pool=state.questions.filter(q=>document.getElementById('exam-section').value==='all'||q._bank===document.getElementById('exam-section').value);
  if(!pool.length)return toast('No questions available in this section.');
  if(document.getElementById('exam-random').checked)pool=[...pool].sort(()=>Math.random()-.5);
  const count=document.getElementById('exam-count').value;examState.pool=count==='all'?pool:pool.slice(0,Math.min(Number(count),pool.length));
  examState.answers={};examState.marked=[];examState.index=0;examState.duration=Number(document.getElementById('exam-duration').value);examState.seconds=examState.duration*60;examState.positive=Math.max(0,Number(document.getElementById('exam-positive').value)||0);examState.negative=Math.max(0,Number(document.getElementById('exam-negative').value)||0);examState.startedAt=Date.now();examState.submitted=false;examState.title=document.getElementById('exam-section').selectedOptions[0].textContent;
  document.getElementById('exam-setup').classList.add('hide');document.getElementById('exam-results').classList.add('hide');document.getElementById('exam-live').classList.remove('hide');
  examRender();clearInterval(examState.timer);examState.timer=setInterval(()=>{examState.seconds--;examUpdateTimer();if(examState.seconds<=0)examSubmit(true);},1000);
}
function examUpdateTimer(){const el=document.getElementById('exam-clock');if(!el)return;const m=Math.floor(Math.max(0,examState.seconds)/60),s=Math.max(0,examState.seconds)%60;el.textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');el.classList.toggle('warning',examState.seconds<=300);}
function examRender(){
  const q=examState.pool[examState.index],chosen=examState.answers[q.id]||'';
  document.getElementById('exam-live').innerHTML=`<div class="exam-live-head"><div><div class="eyebrow muted">LIVE EXAMINATION · ${esc(examState.title)}</div><b>Question ${examState.index+1} of ${examState.pool.length}</b></div><div class="exam-timer" id="exam-clock">--:--</div></div>
  <div class="exam-live-grid"><section class="panel exam-question"><div class="question-card-top"><span class="q-kicker">QUESTION ${examState.index+1} / ${examState.pool.length}</span><div class="q-tags"><span class="q-tag">${esc(q.difficulty)}</span><span class="q-tag">${esc(q.topic)}</span></div></div><div class="exam-qtext">${esc(q.question)}</div><div>${q.options.map(([k,v])=>`<button class="exam-option ${chosen===k?'chosen':''}" data-exam-option="${esc(k)}"><span class="letter">${esc(k)}</span><span>${esc(v)}</span></button>`).join('')}</div>
  <div class="exam-actions"><button class="btn btn-primary" id="exam-save-next">Save & Next →</button><button class="btn btn-dark" id="exam-flag">${examState.marked.includes(q.id)?'★ Unmark review':'☆ Mark for review'}</button><button class="text-btn" id="exam-clear">Clear response</button><button class="text-btn" id="exam-prev">← Previous</button><button class="text-btn" id="exam-submit">Submit examination</button></div></section>
  <aside class="panel exam-palette"><div class="eyebrow muted">QUESTION PALETTE</div><h3>Navigate your paper</h3><div class="exam-palette-grid">${examState.pool.map((x,i)=>`<button class="palette-btn ${examState.answers[x.id]?'answered':''} ${examState.marked.includes(x.id)?'flagged':''} ${i===examState.index?'current':''}" data-exam-jump="${i}">${i+1}</button>`).join('')}</div><div class="exam-legend"><span style="background:#b7e8d1"></span>Answered <span style="background:#f4d18a"></span>Review flagged <span style="background:#e8e7ef"></span>Not answered</div><div class="result-row"><span>Answered</span><b>${Object.keys(examState.answers).length} / ${examState.pool.length}</b></div><div class="result-row"><span>Marked for review</span><b>${examState.marked.length}</b></div></aside></div>`;
  examUpdateTimer();
  document.querySelectorAll('[data-exam-option]').forEach(b=>b.addEventListener('click',()=>{examState.answers[q.id]=b.dataset.examOption;examRender()}));
  document.querySelectorAll('[data-exam-jump]').forEach(b=>b.addEventListener('click',()=>{examState.index=Number(b.dataset.examJump);examRender()}));
  document.getElementById('exam-save-next').addEventListener('click',()=>{if(examState.index<examState.pool.length-1){examState.index++;examRender()}else examSubmit(false)});
  document.getElementById('exam-flag').addEventListener('click',()=>{examState.marked=examState.marked.includes(q.id)?examState.marked.filter(x=>x!==q.id):[...examState.marked,q.id];examRender()});
  document.getElementById('exam-clear').addEventListener('click',()=>{delete examState.answers[q.id];examRender()});
  document.getElementById('exam-prev').addEventListener('click',()=>{if(examState.index>0){examState.index--;examRender()}});
  document.getElementById('exam-submit').addEventListener('click',()=>examSubmit(false));
}
function examSubmit(auto){
  if(examState.submitted)return;const unanswered=examState.pool.filter(q=>!examState.answers[q.id]).length;
  if(!auto&&document.getElementById('exam-confirm')?.checked&&!confirm(`Submit this examination? ${unanswered} question(s) are unanswered.`))return;
  examState.submitted=true;clearInterval(examState.timer);
  let correct=0,wrong=0,skip=0;examState.pool.forEach(q=>{const a=examState.answers[q.id];if(!a){skip++;return;}if(a===q.correct_option)correct++;else wrong++;scheduleAnswer(q,a,'exam');});
  save();const score=correct*examState.positive-wrong*examState.negative,attempted=correct+wrong,acc=attempted?Math.round(correct/attempted*100):0;
  document.getElementById('exam-live').classList.add('hide');const out=document.getElementById('exam-results');out.classList.remove('hide');
  out.innerHTML=`<div class="panel"><div class="exam-result-head"><div class="eyebrow muted">${auto?'TIME EXPIRED · AUTO SUBMITTED':'EXAMINATION SUBMITTED'}</div><h2 style="font:800 25px var(--head)">Your result</h2><div class="result-score">${score.toFixed(2)}<small style="font:500 11px var(--font);color:#999"> net marks</small></div><p class="muted-text">${examState.pool.length} questions · ${Math.floor((Date.now()-examState.startedAt)/60000)} min elapsed</p></div>
  <div class="exam-stat-grid"><div class="exam-stat"><span>Correct</span><b>${correct}</b></div><div class="exam-stat"><span>Incorrect</span><b>${wrong}</b></div><div class="exam-stat"><span>Unanswered</span><b>${skip}</b></div><div class="exam-stat"><span>Accuracy</span><b>${acc}%</b></div></div>
  <div class="result-list"><div class="result-row"><span>Marks obtained</span><b>${score.toFixed(2)}</b></div><div class="result-row"><span>Maximum marks</span><b>${(examState.pool.length*examState.positive).toFixed(2)}</b></div><div class="result-row"><span>Marking scheme</span><b>+${examState.positive} / −${examState.negative}</b></div><div class="result-row"><span>Review flags</span><b>${examState.marked.length}</b></div></div>
  <div class="exam-result-toolbar"><button class="btn btn-primary" id="exam-review-all">Review answers & explanations</button><button class="btn btn-dark" id="exam-back-setup">New examination</button></div><div id="exam-review" class="hide"></div></div>`;
  document.getElementById('exam-review-all').addEventListener('click',()=>{const r=document.getElementById('exam-review');r.classList.toggle('hide');r.innerHTML=examState.pool.map((q,i)=>{const a=examState.answers[q.id],ok=a===q.correct_option;return `<div class="exam-review-row"><b>${i+1}. ${esc(q.question)}</b><span class="${!a?'skip':ok?'ok':'bad'}">${!a?'Not answered':ok?'Correct':'Incorrect'} · Your answer: ${esc(a||'—')} · Correct: ${esc(q.correct_option)}</span><p>${esc(q.explanation||'No explanation was supplied in this question-bank file.')}</p></div>`}).join('')});
  document.getElementById('exam-back-setup').addEventListener('click',()=>{out.classList.add('hide');document.getElementById('exam-setup').classList.remove('hide');examInject();});
  refresh();
}
function examBoot(){
  examInject();
  const start=document.getElementById('exam-start');if(start)start.addEventListener('click',examStart);
}

/* PHASE 3 — ADVANCED PERFORMANCE ANALYTICS */
document.addEventListener('DOMContentLoaded',()=>{const st=document.createElement('style');st.textContent="\n.analytics-deep-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:14px 0}\n.analytics-breakdown{margin-top:14px}.analytics-row{margin:13px 0}.analytics-row-head{display:flex;justify-content:space-between;gap:10px;font-size:10px;margin-bottom:6px}.analytics-row-head span{color:#85849a;white-space:nowrap}.analytics-track{height:7px;border-radius:8px;background:#f0eff5;overflow:hidden}.analytics-track i{display:block;height:100%;background:linear-gradient(90deg,#7b61dc,#42b7a5);border-radius:8px}\n.priority-row{padding:10px 0;border-bottom:1px solid #efedf4}.priority-row b,.priority-row span{display:block}.priority-row b{font-size:11px}.priority-row span{font-size:9px;color:#9291a5;margin-top:4px}\n.analytics-streak{font-size:10px;font-weight:800;color:#7657e8;background:#f3f0ff;padding:8px 11px;border-radius:20px}\n.activity-chart{display:grid;grid-template-columns:repeat(14,minmax(0,1fr));gap:8px;align-items:end;height:112px;margin-top:18px}.activity-day{text-align:center;min-width:0}.activity-bar-wrap{height:82px;display:flex;align-items:end;background:#f7f6fa;border-radius:7px;overflow:hidden}.activity-bar-wrap i{display:block;width:100%;background:#7d65df;border-radius:6px 6px 0 0;min-height:2px}.activity-day small{display:block;color:#9695a8;font-size:8px;margin-top:7px}.activity-foot{font-size:10px;color:#9392a5;margin-top:12px}\n.snapshot-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.snapshot-grid div{padding:12px;background:#faf9fd;border-radius:10px}.snapshot-grid b,.snapshot-grid span{display:block}.snapshot-grid b{font:800 22px var(--head);color:#7657e8}.snapshot-grid span{font-size:9px;color:#9291a5;margin-top:4px}\n@media(max-width:760px){.analytics-deep-grid{grid-template-columns:1fr}.activity-chart{gap:3px}.activity-day small{font-size:7px}}\n";document.head.appendChild(st);});
function analyticsRender(){
  const vals=Object.values(state.attempts||{}), total=vals.length;
  const groups=(key)=>{const out={};vals.forEach(a=>{const k=(a[key]||'Unclassified').trim();out[k]??={n:0,c:0,wrong:0};out[k].n++;if(a.correct)out[k].c++;else out[k].wrong++;});return Object.entries(out).map(([name,v])=>({name,...v,acc:v.n?Math.round(v.c/v.n*100):0}));};
  const subjects=groups('subject').sort((a,b)=>b.acc-a.acc);
  const topics=groups('topic').sort((a,b)=>a.acc-b.acc);
  const renderRows=(arr,limit=10)=>arr.slice(0,limit).map(x=>`<div class="analytics-row"><div class="analytics-row-head"><b>${esc(x.name)}</b><span>${x.acc}% · ${x.c}/${x.n}</span></div><div class="analytics-track"><i style="width:${x.acc}%"></i></div></div>`).join('');
  const sec=document.getElementById('subject-performance');if(sec)sec.innerHTML=subjects.length?renderRows(subjects):'<div class="empty-state">No subject data yet.</div>';
  const weak=document.getElementById('weak-topics');if(weak)weak.innerHTML=topics.length?renderRows(topics.filter(x=>x.n>=2).slice(0,8)): '<div class="empty-state">Topic-level data will appear after practice.</div>';
  const priorities=vals.filter(a=>!a.correct).sort((a,b)=>(b.lapses||0)-(a.lapses||0)||(a.nextReview||0)-(b.nextReview||0)).slice(0,8);
  const pri=document.getElementById('revision-priority');if(pri)pri.innerHTML=priorities.length?priorities.map(a=>`<div class="priority-row"><b>${esc(a.topic||'Uncategorised topic')}</b><span>${esc(a.subject||a.bank||'')} · ${a.lapses||1} miss(es)</span></div>`).join(''):'<div class="empty-state">No incorrect answers recorded. Keep practising to build your profile.</div>';
  const now=new Date(), days=[];
  for(let i=13;i>=0;i--){const d=new Date(now);d.setHours(0,0,0,0);d.setDate(d.getDate()-i);const key=d.toDateString();const n=vals.filter(a=>a.date&&new Date(a.date).toDateString()===key).length;days.push({d,n,label:d.toLocaleDateString(undefined,{weekday:'short'}),today:i===0});}
  const chart=document.getElementById('activity-chart');if(chart)chart.innerHTML=days.map(x=>`<div class="activity-day" title="${x.d.toLocaleDateString()}: ${x.n} recorded questions"><div class="activity-bar-wrap"><i style="height:${x.n?Math.max(8,Math.min(100,x.n*12)):3}%"></i></div><small>${x.label}</small></div>`).join('');
  const active=days.filter(x=>x.n).length, todayCount=days[13].n;
  let streak=0;for(let i=13;i>=0;i--){if(days[i].n)streak++;else if(streak||i!==13)break;}
  const st=document.getElementById('study-streak');if(st)st.textContent=`${streak}-day streak`;
  const sum=document.getElementById('activity-summary');if(sum)sum.textContent=`${active} active days in the last 14 · ${todayCount} recorded today · ${vals.reduce((n,a)=>n+(a.lapses||0),0)} cumulative misses`;
  const snap=document.getElementById('learning-snapshot');if(snap){const mastered=vals.filter(a=>(a.repetitions||0)>=4).length,due=dueQuestions().length,correct=vals.filter(a=>a.correct).length;snap.innerHTML=`<div class="snapshot-grid"><div><b>${total}</b><span>Questions attempted</span></div><div><b>${total?Math.round(correct/total*100):0}%</b><span>Overall accuracy</span></div><div><b>${mastered}</b><span>Mastered</span></div><div><b>${due}</b><span>Due for revision</span></div></div>`;}
}
function analyticsBoot(){
  const nav=document.querySelector('.nav-list');
  if(nav&&!document.querySelector('[data-view="analytics"]')){
    const b=document.createElement('button');b.className='nav-link';b.dataset.view='analytics';b.innerHTML='<i>▥</i> Performance analytics';b.addEventListener('click',()=>go('analytics'));nav.insertBefore(b,nav.querySelector('[data-view="exam"]')||nav.firstChild);
  }
  analyticsRender();
}
const oldRefreshPhase3=refresh;
refresh=function(){oldRefreshPhase3();analyticsRender();};
