init=async function(){await oldInit();examBoot();analyticsBoot();};


/* PHASE 4 — DESCRIPTIVE ANSWER EVALUATOR + FULL-TEXT PDF SEARCH */
const evaluatorState={};
function evaluatorInject(){
 const nav=document.querySelector('.nav-list');
 if(nav&&!document.querySelector('[data-view="evaluator"]')){
  const b=document.createElement('button');b.className='nav-link';b.dataset.view='evaluator';b.innerHTML='<i>✎</i> Descriptive evaluator';b.addEventListener('click',()=>go('evaluator'));nav.insertBefore(b,nav.querySelector('[data-view="analytics"]')||nav.firstChild);
 }
 const wrap=document.querySelector('.page-wrap');
 if(wrap&&!document.getElementById('view-evaluator')){
  const sec=document.createElement('section');sec.className='view';sec.id='view-evaluator';
  sec.innerHTML=`<div class="page-title-row"><div><div class="eyebrow muted">STRUCTURED SELF-ASSESSMENT</div><h1>Descriptive answer evaluator<span class="title-dot">.</span></h1><p>Evaluate answer coverage against your own marking points, improve structure and identify missing content.</p></div></div>
  <div class="evaluator-grid"><section class="panel evaluator-form">
   <label>Question / answer prompt<textarea id="eval-question" rows="2" placeholder="Paste or write the descriptive question..."></textarea></label>
   <div class="evaluator-two"><label>Maximum marks<input id="eval-max-marks" type="number" min="1" max="100" value="10"></label><label>Target word count<input id="eval-target-words" type="number" min="50" max="3000" value="250"></label></div>
   <label>Expected marking points <small>(one point per line; add the key facts an ideal answer should cover)</small><textarea id="eval-rubric" rows="7" placeholder="Definition / meaning&#10;Causes or classification&#10;Mechanism / process&#10;Examples or applications&#10;Prevention / control / legal provisions"></textarea></label>
   <label>Your answer<textarea id="eval-answer" rows="12" placeholder="Write or paste your descriptive answer here..."></textarea></label>
   <div class="evaluator-actions"><button class="btn btn-primary" id="eval-run">Evaluate my answer</button><button class="btn btn-dark" id="eval-clear">Clear</button></div>
   <p class="evaluator-disclaimer">This is a transparent, rule-based practice aid — not an official HPSC marking scheme, examiner score or AI assessment. It does not verify factual correctness unless your expected points capture the required facts.</p>
  </section><aside class="panel evaluator-guide"><div class="eyebrow muted">HOW TO USE</div><h3>Build a better answer.</h3><ol><li>Enter the exact question.</li><li>Add key points from your notes or teacher’s marking scheme.</li><li>Write your answer in your own words.</li><li>Review matched points, missing areas and structure feedback.</li></ol><div class="evaluator-result hide" id="eval-result"></div></aside></div>`;
  wrap.insertBefore(sec,wrap.querySelector('footer'));
  document.getElementById('eval-run').addEventListener('click',evaluateDescriptive);
  document.getElementById('eval-clear').addEventListener('click',()=>{['eval-question','eval-rubric','eval-answer'].forEach(id=>document.getElementById(id).value='');document.getElementById('eval-result').classList.add('hide');});
 }
}
function evaluateDescriptive(){
 const question=document.getElementById('eval-question').value.trim(),rubric=document.getElementById('eval-rubric').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),answer=document.getElementById('eval-answer').value.trim(),max=Math.max(1,Math.min(100,Number(document.getElementById('eval-max-marks').value)||10)),target=Math.max(50,Number(document.getElementById('eval-target-words').value)||250);
 if(!question||!rubric.length||!answer)return toast('Enter the question, expected marking points and your answer first.');
 const words=answer.match(/\b[\w'-]+\b/g)||[], lower=answer.toLowerCase();
 const stop=new Set('the a an and or of to in on for with by from is are was were be been being this that these those it its as at into than then also can may should must will has have had their they them we you your which what when where how why'.split(' '));
 const matched=[],missing=[];
 rubric.forEach(point=>{
  const tokens=[...new Set((point.toLowerCase().match(/[a-z0-9]+/g)||[]).filter(t=>t.length>2&&!stop.has(t)))];
  const hits=tokens.filter(t=>lower.includes(t));
  const threshold=tokens.length<=2?Math.max(1,tokens.length):Math.max(1,Math.ceil(tokens.length*.45));
  (hits.length>=threshold?matched:missing).push({point,hits:hits.length,total:tokens.length});
 });
 const coverage=rubric.length?matched.length/rubric.length:0;
 const paragraphs=answer.split(/\n\s*\n/).filter(x=>x.trim()).length;
 const hasStructure=/(^|\n)\s*(\d+[.)]|[•*-]|introduction|conclusion|definition|causes|types|prevention|management|haccp|advantages|disadvantages)\b/i.test(answer);
 const wordRatio=words.length/target;
 const lengthScore=wordRatio>=.7&&wordRatio<=1.3?1:wordRatio>=.45&&wordRatio<=1.6?.65:.3;
 const structureScore=(hasStructure?0.55:0.25)+(paragraphs>=2?0.25:0)+(words.length>=80?0.2:0);
 const totalScore=Math.round(max*(coverage*.7+structureScore*.15+lengthScore*.15)*10)/10;
 const contentMarks=Math.round(max*coverage*.7*10)/10, structureMarks=Math.round(max*structureScore*.15*10)/10,lengthMarks=Math.round(max*lengthScore*.15*10)/10;
 const result=document.getElementById('eval-result');result.classList.remove('hide');
 result.innerHTML=`<div class="eyebrow muted">PRACTICE ESTIMATE</div><div class="eval-score">${totalScore}<small> / ${max}</small></div><p class="eval-score-note">Indicative rubric-based score only</p><div class="eval-score-bars"><div><span>Content coverage</span><b>${Math.round(coverage*100)}%</b></div><div class="analytics-track"><i style="width:${coverage*100}%"></i></div><div><span>Structure</span><b>${Math.round(structureScore*100)}%</b></div><div class="analytics-track"><i style="width:${structureScore*100}%"></i></div><div><span>Length fit</span><b>${Math.round(lengthScore*100)}%</b></div><div class="analytics-track"><i style="width:${lengthScore*100}%"></i></div></div><h4>Covered marking points (${matched.length}/${rubric.length})</h4>${matched.length?matched.map(x=>`<div class="eval-point covered">✓ ${esc(x.point)}</div>`).join(''):'<p>No expected points were matched clearly.</p>'}<h4>Areas to add or strengthen (${missing.length})</h4>${missing.length?missing.map(x=>`<div class="eval-point missing">＋ ${esc(x.point)}</div>`).join(''):'<p>All entered marking points were matched.</p>'}<h4>Writing feedback</h4><ul class="eval-feedback"><li>${words.length} words; target ${target} words.</li><li>${paragraphs} paragraph(s) detected.</li><li>${hasStructure?'Some answer structure or headings detected.':'Use headings, numbered steps or a clear introduction and conclusion.'}</li><li>Content component: ${contentMarks}/${max} weighted marks; structure: ${structureMarks}; length: ${lengthMarks}.</li></ul>`;
}
async function pdfSearchBoot(){
 const input=document.getElementById('pdf-content-search');if(!input||input.dataset.ready)return;input.dataset.ready='1';
 let pages=[];const status=document.getElementById('pdf-search-status'),results=document.getElementById('pdf-search-results');
 try{const response=await fetch('content/search/pdf-index.json');if(!response.ok)throw Error('index unavailable');pages=await response.json();status.textContent=`Full-text search ready · ${pages.length} indexed PDF pages across 10 documents.`;}
 catch(e){status.textContent='Could not load the PDF search index. Make sure the site is running through the local server (not opened as a file).';return;}
 let timer;input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{
  const q=input.value.trim().toLowerCase();if(q.length<2){results.innerHTML='';status.textContent=`Full-text search ready · ${pages.length} indexed PDF pages across 10 documents.`;return;}
  const terms=q.split(/\s+/).filter(Boolean);const hits=[];
  pages.forEach(p=>{const text=p.text.toLowerCase();const count=terms.reduce((n,t)=>n+(text.includes(t)?1:0),0);if(count===terms.length){const pos=Math.max(0,text.indexOf(terms[0]));const start=Math.max(0,pos-105),end=Math.min(p.text.length,pos+240);hits.push({p,count,snippet:(start?'…':'')+p.text.slice(start,end)+(end<p.text.length?'…':'')});}});
  hits.sort((a,b)=>b.count-a.count);const shown=hits.slice(0,40);
  status.textContent=`${hits.length} matching page(s) · showing ${shown.length}${hits.length>40?' best matches':''}.`;
  results.innerHTML=shown.length?shown.map(h=>`<a class="pdf-hit" href="${h.p.file}#page=${h.p.page}" target="_blank" rel="noopener"><span class="pdf-hit-top"><b>${esc(h.p.doc)}</b><strong>Page ${h.p.page} ↗</strong></span><span>${esc(h.snippet)}</span></a>`).join(''):'<div class="empty-state">No exact all-term match. Try fewer words or a shorter phrase.</div>';
 },180);});
}
const phase4OldInit=init;
init=async function(){await phase4OldInit();evaluatorInject();pdfSearchBoot();};
