 function topicStats(){const vals=Object.values(state.attempts||{}),map={};vals.forEach(a=>{const k=a.topic||'General';map[k]??={n:0,wrong:0,last:0};map[k].n++;if(!a.correct)map[k].wrong++;map[k].last=Math.max(map[k].last,a.date||a.lastReviewed||0);});return Object.entries(map).map(([topic,v])=>({topic,...v,accuracy:Math.round((v.n-v.wrong)/v.n*100)})).sort((a,b)=>a.accuracy-b.accuracy||b.wrong-a.wrong);}
 function renderPlanner(){if(!$id('planner-tasks'))return;const mins=Math.max(15,Math.min(600,Number($id('plan-minutes').value)||120)),days=Number($id('plan-days').value)||7;const due=typeof dueQuestions==='function'?dueQuestions().length:0,stats=topicStats(),weak=stats.filter(x=>x.n>=2).slice(0,3),newTopics=[...new Set((state.questions||[]).map(q=>q.topic||'General'))].filter(t=>!stats.some(s=>s.topic===t));const tasks=[];let remaining=mins;if(due){const t=Math.min(35,Math.max(15,Math.round(mins*.25)));tasks.push({m:t,title:'Smart revision queue',detail:`Review ${due} questions currently due in your spaced-repetition schedule.`,tag:'DUE REVISION'});remaining-=t;}weak.forEach((x,i)=>{if(remaining>0){const t=Math.min(30,Math.max(15,Math.round(mins*.2)));tasks.push({m:t,title:`Strengthen: ${x.topic}`,detail:`Recorded accuracy ${x.accuracy}% across ${x.n} attempts. Revisit notes, then practise this topic.`,tag:'WEAK AREA'});remaining-=t;}});if(remaining>0&&newTopics.length){const t=Math.min(35,remaining);tasks.push({m:t,title:`Learn a new topic: ${newTopics[0]}`,detail:'Read the matching notes and attempt a focused set of questions.',tag:'NEW LEARNING'});remaining-=t;}if(remaining>0){tasks.push({m:remaining,title:'Mixed practice + error review',detail:'Complete a mixed question set and review every incorrect response.',tag:'CONSOLIDATION'});}const total=tasks.reduce((a,x)=>a+x.m,0);$id('planner-summary').innerHTML=`<b>${mins} minutes planned</b> · ${due} due revisions · ${weak.length} weak topics identified · ${days===1?'Today':'A reusable daily template for the next 7 days'}. ${stats.length?'Recommendations are based on your recorded attempts.':'Start practising to unlock more personalised recommendations.'}`;$id('planner-tasks').innerHTML=tasks.map((t,i)=>`<article class="plan-task"><div class="plan-time">${t.m}<small> min</small></div><div><b>${esc(t.title)}</b><small>${esc(t.detail)}</small></div><em>${esc(t.tag)}</em></article>`).join('');}
 function renderGeminiMarkdown(markdown='') {
  const inline = value => esc(value)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, '<em>$1</em>');
  const lines = String(markdown).replace(/\r/g, '').split('\n');
  let html = '', paragraph = [], listType = null, inCode = false, code = [], codeLang='';
  const closeList = () => { if (listType) { html += `</${listType}>`; listType = null; } };
  const flushParagraph = () => { if (paragraph.length) { html += `<p>${paragraph.map(inline).join('<br>')}</p>`; paragraph = []; } };
  for (let li=0; li<lines.length; li++) {
    const line=lines[li];
    if (/^\s*```/.test(line)) {
      flushParagraph(); closeList();
      if (inCode) { const raw=code.join('\n'); html += /^(flowchart|graph)\s+(TD|TB|LR|RL|BT)/m.test(raw) ? renderSimpleFlowchart(raw) : `<pre><code>${esc(raw)}</code></pre>`; code = []; inCode = false; codeLang=''; }
      else { inCode = true; codeLang=(line.match(/^\s*```([\w-]*)/)||[])[1]||''; }
      continue;
    }
    if (inCode) { code.push(line); continue; }
    if (!line.trim()) { flushParagraph(); closeList(); continue; }
    if (line.includes('|') && /^\s*\|?\s*:?-{3,}/.test(lines[li+1]||'')) { flushParagraph(); closeList(); const rows=[]; let j=li; while(j<lines.length && lines[j].includes('|')){const cells=lines[j].trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim()); if(!cells.every(x=>/^:?-{3,}:?$/.test(x))) rows.push(cells); j++;} const head=rows.shift()||[]; html+='<div class="answer-table-wrap"><table class="answer-table"><thead><tr>'+head.map(c=>`<th>${inline(c)}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+head.map((_,i)=>`<td>${inline(r[i]||'')}</td>`).join('')+'</tr>').join('')+'</tbody></table></div>'; li=j-1; continue; }
    const heading = line.match(/^\s{0,3}(#{1,4})\s+(.+)$/);
    if (heading) { flushParagraph(); closeList(); const level = heading[1].length + 1; html += `<h${level}>${inline(heading[2])}</h${level}>`; continue; }
    if (/^\s*(---+|___+|\*\*\*+)\s*$/.test(line)) { flushParagraph(); closeList(); html += '<hr>'; continue; }
    const quote=line.match(/^\s*>\s?(.*)$/); if(quote){flushParagraph();closeList();html+=`<blockquote class="answer-callout">${inline(quote[1])}</blockquote>`;continue;}
    const bullet = line.match(/^\s*[-*+]\s+(.+)$/);
    const numbered = line.match(/^\s*\d+[.)]\s+(.+)$/);
    if (bullet || numbered) {
      flushParagraph(); const type = bullet ? 'ul' : 'ol';
      if (listType !== type) { closeList(); html += `<${type}>`; listType = type; }
      html += `<li>${inline((bullet || numbered)[1])}</li>`; continue;
    }
    closeList(); paragraph.push(line.trim());
  }
  flushParagraph(); closeList();
  if (inCode) html += `<pre><code>${esc(code.join('\n'))}</code></pre>`;
  return html || '<p>No answer returned.</p>';
}

 async function geminiAsk(){
  const q=$id('gemini-query')?.value.trim(),out=$id('gemini-response'),button=$id('gemini-ask');
  const answerLength=$id('gemini-answer-length')?.value||'medium';
  const selectedModel=$id('gemini-model')?.value||'auto';
  if(!q||q.length<2){toast('Enter a question first.');return;}
  if(!aiAccessToken){out.innerHTML='<div class="gemini-status">Sign in with your AI-authorised account first.</div>';return;}
  if(button?.disabled)return;
  if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='Preparing answer…';}
  out.innerHTML='<div class="gemini-status">Searching your notes and preparing a structured, source-grounded answer…</div>';
  try{
   if(!foodsafePdfIndex){const r=await fetch('content/search/pdf-index.json');if(!r.ok)throw Error('Could not load the PDF search index.');foodsafePdfIndex=await r.json();}
   const terms=[...new Set(q.toLowerCase().match(/[a-z0-9-]+/g)||[])].filter(t=>t.length>2&&!['what','which','when','where','why','how','explain','describe','about','with','from','this','that','into','are','the','and','for','does','can'].includes(t));
   const ranked=foodsafePdfIndex.map(p=>({p,score:terms.reduce((n,t)=>n+(p.text.toLowerCase().includes(t)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,5);
   if(!ranked.length)throw Error('No matching passages were found in the notes. Try a technical term or shorter question.');
   const sources=ranked.map(x=>({document:x.p.doc,page:x.p.page,file:x.p.file,text:x.p.text.slice(0,1800)}));
   const response=await fetch(foodsafeApiUrl('/api/ask'),{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+aiAccessToken},body:JSON.stringify({question:q,sources,answerLength,model:selectedModel})});
   const data=await response.json();if(!response.ok){if(response.status===401){aiAccessToken=null;renderGeminiView();}throw Error(data.error||'Gemini request failed.');}
   const citations=sources.map((x,i)=>`<a href="${esc(x.file)}#page=${Number(x.page)||1}" target="_blank" rel="noopener">[${i+1}] ${esc(x.document)} — page ${Number(x.page)||1} ↗</a>`).join('');
   const answerRecord={id:'ai_'+Date.now()+'_'+Math.random().toString(36).slice(2,8),question:q,answer:data.answer||'No answer returned.',citations:sources.map((x,i)=>({label:`[${i+1}] ${x.document} — page ${Number(x.page)||1}`,url:`${x.file}#page=${Number(x.page)||1}`})),provider:data.provider||'AI',model:data.model||'',length:answerLength,createdAt:new Date().toISOString(),bookmarked:false}; window.foodsafeCurrentAiAnswer=answerRecord;
   out.innerHTML=`<div class="assistant-answer-heading">Study answer <span class="answer-depth-label">${esc(answerLength.toUpperCase())}</span> <span class="answer-depth-label">${esc(data.provider||'AI')} · ${esc(data.model||'')}</span></div><div class="ai-answer-actions"><button type="button" class="btn btn-primary" id="ai-save-answer">＋ Save answer</button><button type="button" class="ai-action-secondary" id="ai-bookmark-answer">☆ Bookmark</button></div><article class="gemini-answer">${renderGeminiMarkdown(data.answer||'No answer returned.')}</article><h3>Sources used</h3><div class="gemini-citations">${citations}</div><p class="assistant-source-note">AI questions used today: ${data.used_today}/${data.daily_limit}. The answer is grounded in retrieved excerpts; check the cited pages for complete context.</p>`;
   $id('ai-save-answer')?.addEventListener('click',saveCurrentAiAnswer);$id('ai-bookmark-answer')?.addEventListener('click',toggleCurrentAiBookmark);
  }catch(e){out.innerHTML=`<div class="gemini-status">${esc(e.message)}</div>`;}
  finally{if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Ask AI ↗';}}
 }

 function getAiAnswers(){return activeFoodsafeUser?load(userStoreKey('aiAnswers'),[]):[];}
 function putAiAnswers(items){if(activeFoodsafeUser)localStorage.setItem(userStoreKey('aiAnswers'),JSON.stringify(items));}
 function saveCurrentAiAnswer(){const a=window.foodsafeCurrentAiAnswer;if(!a)return;const items=getAiAnswers();if(items.some(x=>x.id===a.id)){toast('This answer is already saved.');return;}items.unshift({...a,savedAt:new Date().toISOString()});putAiAnswers(items);renderSavedAiAnswers();toast('Answer saved to your revision library.');const b=$id('ai-save-answer');if(b)b.textContent='✓ Saved';}
 function toggleCurrentAiBookmark(){const a=window.foodsafeCurrentAiAnswer;if(!a)return;const items=getAiAnswers(),i=items.findIndex(x=>x.id===a.id);if(i<0){items.unshift({...a,savedAt:new Date().toISOString(),bookmarked:true});}else items[i].bookmarked=!items[i].bookmarked;putAiAnswers(items);a.bookmarked=i<0?true:items[i].bookmarked;const b=$id('ai-bookmark-answer');if(b)b.textContent=a.bookmarked?'★ Bookmarked':'☆ Bookmark';renderSavedAiAnswers();toast(a.bookmarked?'Added to bookmarks.':'Bookmark removed.');}
 function renderSavedAiAnswers(){const host=$id('saved-ai-list');if(!host)return;const term=($id('saved-ai-search')?.value||'').toLowerCase(),filter=$id('saved-ai-filter')?.value||'all';const items=getAiAnswers().filter(a=>(filter!=='bookmarked'||a.bookmarked)&&(!term||(a.question+' '+a.answer).toLowerCase().includes(term)));host.innerHTML=items.length?items.map(a=>`<article class="saved-ai-card"><div class="saved-ai-meta"><span>${esc(a.provider||'AI')} · ${esc(a.length||'medium')} · ${new Date(a.createdAt||a.savedAt).toLocaleDateString()}</span><span>${a.bookmarked?'★ BOOKMARKED':'SAVED'}</span></div><h3>${esc(a.question)}</h3><div class="saved-ai-preview">${renderGeminiMarkdown(a.answer).slice(0,1800)}</div><div class="saved-ai-actions"><button type="button" data-open-ai="${esc(a.id)}">Open full answer</button><button type="button" data-toggle-ai="${esc(a.id)}">${a.bookmarked?'Remove bookmark':'Bookmark'}</button><button type="button" data-delete-ai="${esc(a.id)}">Delete</button></div></article>`).join(''):'<div class="empty-state">No saved answers yet. Generate an AI answer and choose Save answer or Bookmark.</div>';host.querySelectorAll('[data-open-ai]').forEach(b=>b.onclick=()=>{const a=getAiAnswers().find(x=>x.id===b.dataset.openAi);if(!a)return;go('gemini');const out=$id('gemini-response');window.foodsafeCurrentAiAnswer=a;out.innerHTML=`<div class="assistant-answer-heading">Saved study answer <span class="answer-depth-label">${esc((a.length||'medium').toUpperCase())}</span></div><div class="ai-answer-actions"><button type="button" class="btn btn-primary" id="ai-save-answer">✓ Saved</button><button type="button" class="ai-action-secondary" id="ai-bookmark-answer">${a.bookmarked?'★ Bookmarked':'☆ Bookmark'}</button></div><article class="gemini-answer">${renderGeminiMarkdown(a.answer)}</article><h3>Sources used</h3><div class="gemini-citations">${(a.citations||[]).map(c=>`<a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.label)} ↗</a>`).join('')}</div>`;$id('ai-bookmark-answer')?.addEventListener('click',toggleCurrentAiBookmark);});host.querySelectorAll('[data-toggle-ai]').forEach(b=>b.onclick=()=>{const arr=getAiAnswers(),a=arr.find(x=>x.id===b.dataset.toggleAi);if(a){a.bookmarked=!a.bookmarked;putAiAnswers(arr);renderSavedAiAnswers();}});host.querySelectorAll('[data-delete-ai]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this saved answer?'))return;putAiAnswers(getAiAnswers().filter(x=>x.id!==b.dataset.deleteAi));renderSavedAiAnswers();});}
 function renderSimpleFlowchart(src){const edges=[];const labels=new Map();const re=/([A-Za-z0-9_]+)\s*(?:\[([^\]]+)\]|\(([^)]+)\)|\{([^}]+)\})?/g;for(const m of src.replace(/^\s*(flowchart|graph)\s+(TD|TB|LR|RL|BT)\s*/,'').matchAll(re)){if(!labels.has(m[1]))labels.set(m[1],m[2]||m[3]||m[4]||m[1]);}const ids=[...labels.keys()];if(!ids.length)return `<pre><code>${esc(src)}</code></pre>`;return `<div class="answer-flowchart">${ids.map((id,i)=>`<div class="flow-node ${i===0?'start':i===ids.length-1?'end':''}">${esc(labels.get(id))}</div>${i<ids.length-1?'<div class="flow-arrow">↓</div>':''}`).join('')}</div>`;}
 function backupKeys(){const prefix='foodsafe_user_'+activeFoodsafeUser+'_';return Object.keys(localStorage).filter(k=>k.startsWith(prefix));}
 function exportBackup(){if(!activeFoodsafeUser)return;const keys=backupKeys(),data={format:'FOODSAFE_BACKUP',version:1,username:activeFoodsafeUser,created:new Date().toISOString(),data:Object.fromEntries(keys.map(k=>[k,localStorage.getItem(k)]))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`FOODSAFE_${activeFoodsafeUser}_backup_${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('Backup downloaded.');}
 async function importBackup(e){const f=e.target.files?.[0];e.target.value='';if(!f||!activeFoodsafeUser)return;try{const d=JSON.parse(await f.text());if(d.format!=='FOODSAFE_BACKUP'||!d.data||d.username!==activeFoodsafeUser)throw Error('This backup is invalid or belongs to a different username.');if(!confirm('Merge this backup into the current account? Existing matching records may be replaced.'))return;Object.entries(d.data).forEach(([k,v])=>{if(k.startsWith('foodsafe_user_'+activeFoodsafeUser+'_')&&typeof v==='string')localStorage.setItem(k,v);});state.attempts=load(userStoreKey('attempts'),{});state.bookmarks=load(userStoreKey('bookmarks'),[]);refresh();flashRender?.();renderSavedAiAnswers();toast('Backup restored.');}catch(err){toast(err.message||'Could not restore backup.');}}

 let aiAccessToken=foodsafeSessionToken, aiAccessUsername=null, aiEligible=false;
 function foodsafeApiUrl(path){const base=(window.FOODSAFE_API_BASE||'').replace(/\/$/,'');return base+path;}
 async function secureAiLogout(){const token=foodsafeSessionToken||aiAccessToken;aiAccessToken=null;aiAccessUsername=null;aiEligible=false;if(token){try{await fetch(foodsafeApiUrl('/api/auth/logout'),{method:'POST',headers:{'Authorization':'Bearer '+token}});}catch(e){}}}
 function secureAiViewBoot(){
  const nav=document.querySelector('.nav-list'),wrap=document.querySelector('.page-wrap');
  if(wrap&&!$id('view-gemini')){const sec=document.createElement('section');sec.className='view';sec.id='view-gemini';sec.innerHTML=`<div class="page-title-row"><div><div class="eyebrow muted">RESTRICTED • ADMIN-AUTHORISED</div><h1>FOODSAFE AI tutor<span class="title-dot">.</span></h1><p>Source-grounded explanations from FOODSAFE's uploaded notes.</p></div></div><div class="panel phase-panel" id="gemini-auth-panel"></div><div class="panel assistant-panel hide" id="gemini-chat-panel"><div class="assistant-intro"><span class="assistant-spark">✧</span><div><b>FOODSAFE AI study tutor</b><small id="gemini-quota">101 questions per day · Gemini + OpenAI</small></div></div><div class="assistant-prompts"><button data-gprompt="Explain the principles of HACCP using the notes">HACCP principles</button><button data-gprompt="Explain food adulteration and its detection methods">Food adulteration</button><button data-gprompt="Summarise the key provisions of the Food Safety and Standards Act, 2006">FSS Act</button></div><label class="assistant-input-label">Ask a question about your study material</label><div class="gemini-answer-controls"><label for="gemini-model">AI model</label><select id="gemini-model" aria-label="Choose AI model"><option value="auto" selected>Automatic · Recommended</option><option value="gemini-flash">Gemini Flash</option><option value="gemini-flash-lite">Gemini Flash Lite</option><option value="openai">OpenAI GPT-5.6 Luna</option></select></div><div class="gemini-answer-controls"><label for="gemini-answer-length">Answer detail</label><select id="gemini-answer-length" aria-label="Answer length"><option value="short">Short · Quick revision</option><option value="medium" selected>Medium · Exam-ready</option><option value="long">Long · Detailed topper notes</option></select></div><div class="assistant-input-row"><textarea id="gemini-query" rows="3" placeholder="Ask a detailed question..."></textarea><button class="btn btn-primary" id="gemini-ask">Ask AI ↗</button></div><div id="gemini-response" class="assistant-response"></div><button class="text-btn" id="gemini-logout" type="button">Sign out of Gemini access</button></div>`;wrap.insertBefore(sec,wrap.querySelector('footer'));}
  $id('gemini-ask')?.addEventListener('click',geminiAsk);$id('gemini-query')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();geminiAsk();}});
  document.querySelectorAll('[data-gprompt]').forEach(b=>b.onclick=()=>{$id('gemini-query').value=b.dataset.gprompt;geminiAsk();});
  $id('gemini-logout')?.addEventListener('click',()=>document.getElementById('logout-btn')?.click());
 }
 function addGeminiNav(show){let b=document.querySelector('[data-view="gemini"]');if(show&&!b){const nav=document.querySelector('.nav-list');if(nav){b=document.createElement('button');b.className='nav-link';b.dataset.view='gemini';b.innerHTML='<i>✧</i> Gemini AI tutor';b.onclick=()=>{go('gemini');renderGeminiView();};nav.appendChild(b);}}else if(!show&&b){b.remove();if($id('view-gemini')?.classList.contains('active'))go('assistant');}}
 async function secureAiBoot(){
  addGeminiNav(false);aiEligible=false;aiAccessToken=foodsafeSessionToken;aiAccessUsername=null;
  if(!activeFoodsafeUser||!aiAccessToken)return;
  try{const r=await fetch(foodsafeApiUrl('/api/auth/me'),{headers:{'Authorization':'Bearer '+aiAccessToken}});if(!r.ok){aiAccessToken=null;return;}const d=await r.json();aiEligible=!!d.ai_enabled;aiAccessUsername=d.username;addGeminiNav(aiEligible);if(aiEligible)renderGeminiView();}
  catch(e){/* Standard notes assistant remains available if API is unreachable. */}
 }
 window.foodsafeOnAuthChanged=(d)=>{aiAccessToken=foodsafeSessionToken;aiAccessUsername=d?.username||activeFoodsafeUser;aiEligible=!!d?.ai_enabled;addGeminiNav(aiEligible);if(aiEligible)renderGeminiView();};
 window.foodsafeAuthLogout=async()=>{await secureAiLogout();};

 function renderGeminiView(){
  const panel=$id('gemini-auth-panel'),chat=$id('gemini-chat-panel');if(!panel||!chat)return;
  if(!aiEligible||!activeFoodsafeUser||!aiAccessToken){panel.innerHTML='<b>Gemini access is not enabled for this account.</b><p>The standard Study Assistant remains available. AI access is granted only by the FOODSAFE administrator.</p>';chat.classList.add('hide');return;}
  panel.innerHTML=`<div class="row-between"><b>AI access active for ${esc(aiAccessUsername||activeFoodsafeUser)}</b><span class="tag">${DAILY_AI_LIMIT} questions/day</span></div><p>Your account is authenticated by Cloudflare. Gemini and OpenAI API keys remain private Worker secrets and are never sent to this browser.</p>`;chat.classList.remove('hide');
 }
 const DAILY_AI_LIMIT=101;

